('business','{"name":"Aureson Apparels","email":"sales@aureson.in","phone":"+91 88709 72097","whatsapp":"918870972097","location":"Tiruppur, Tamil Nadu, India","instagram":"https://www.instagram.com/aureson_apparels/","about":"Founded in 2022 in Tiruppur, Tamil Nadu, Aureson Apparels creates quality knitted garments for individuals, brands and businesses. From ready-stock apparel to custom printing and embroidery, we bring your clothing ideas to life."}'),
('content','{"announcementEnabled":true,"announcement":"From Tiruppur, with craft. Custom apparel enquiries from 30 pieces.","heroTitle":"Your vision. Our craftsmanship.","heroDescription":"Thoughtfully made apparel. Personalised for your brand, your team, and your everyday.","heroImage":"/img/IMGL7732.JPG","bulkTitle":"Your brand. Worn with pride.","bulkDescription":"From the first idea to the final stitch. Create custom apparel with printing, embroidery and fabric choices that fit your vision."}'),
('store','{"currency":"INR","checkoutEnabled":false,"taxBasisPoints":null,"policiesApproved":false,"lowStockThreshold":5,"minimumBulkQuantity":30,"notificationsEnabled":false}'),
('policies','{"privacy":"We collect the contact, delivery and order details you submit to process enquiries and purchases. For questions about your information, contact sales@aureson.in. A complete privacy policy requires business approval before checkout is enabled.","terms":"Bulk orders require quotation and sample or preview approval. The supplied business information specifies a 50% advance and no cancellation once the advance is paid and production has started. Full terms require business approval before checkout is enabled.","shipping":"We deliver across India. Dispatch for small minimum-quantity custom orders is approximately one week, subject to quantity, style and sample approval. Delivery rates and timelines are confirmed with your quotation. Published shipping rates require clarification before online checkout is enabled.","returns":"Contact us within 3 days of delivery regarding damaged products or size exchange. The supplied business information states that customized products are not eligible for returns or exchanges. Full eligibility, process and refund terms require business approval before checkout is enabled."}');
